/**
* @file arkrtos_shell_auth.c
* @brief Console login for the kernel shell: password gate, login/logout.
* @details The board stores neither the password nor anything derived from it
*          reversibly: it stores a 16 byte salt and sha256(salt || password),
*          both injected at compile time (ARKRTOS_SHELL_AUTH_SALT /
*          ARKRTOS_SHELL_AUTH_DIGEST, generated by tools/shell_auth_cred.py).
*          The comparison is a full 32 byte XOR-accumulate with no early exit,
*          so a wrong password costs the same time wherever it first differs.
*
*          Failure policy: ARKRTOS_SHELL_AUTH_TRIES consecutive wrong
*          passwords lock the console hard until the next reset.  No delay,
*          no exponential backoff - on a serial line a delay only makes
*          guessing cheaper per unit of wall-clock time.
*
*          What this does NOT do (see docs/安全认证准备.md):
*            - the password crosses the serial line in clear;
*            - the digest is in the image, so a leaked image can be
*              brute-forced offline against a weak password;
*            - it is not a device identity (that is SEC-G13) and it does not
*              stop a full Flash rewrite.
*          It answers one question: is the person typing on the console the
*          operator.
* @author xw
*/

#include "arkrtos_features.h"

#if (ARKRTOS_USE_SHELL_AUTH == 1)

#include "arkrtos_shell_auth.h"
#include "arkrtos_sha256.h"
#include "ark_shell.h"          /* ark_shell_printf */
#if (ARKRTOS_USE_AUDIT_LOG == 1)
#include "arkrtos_audit_log.h"
#endif

/* Injected by -DARKRTOS_SHELL_AUTH_LOCAL=1 -> arkrtos_shell_auth_local.h,
 * which the build generates (example/qemu_loongarch64/Makefile) and which
 * .gitignore keeps out of the tree.  arkrtos_features.h already #error'd if
 * either symbol is missing, so these two lines cannot silently become zero. */
static const uint8 s_auth_salt[16]   = ARKRTOS_SHELL_AUTH_SALT;
static const uint8 s_auth_digest[32] = ARKRTOS_SHELL_AUTH_DIGEST;

static int s_auth_locked      = 1;   /* boot starts locked */
static int s_auth_locked_hard = 0;   /* wrong-password limit reached */
static int s_auth_fails       = 0;

/* --------------------------------------------------------------- helpers */

static uint32 auth_strlen(const char *s)
{
    uint32 n = 0u;

    while(s[n] != '\0')
    {
        n++;
    }
    return n;
}

static int auth_streq(const char *a, const char *b)
{
    uint32 i = 0u;

    if((a == 0) || (b == 0))
    {
        return 0;
    }
    while((a[i] != '\0') && (a[i] == b[i]))
    {
        i++;
    }
    return (a[i] == b[i]) ? 1 : 0;
}

/* Constant time in the *content*: always 32 iterations, diff accumulates
 * every differing byte.  (The length is a compile-time 32, so there is no
 * length channel either.) */
static int auth_digest_equal(const uint8 *a, const uint8 *b, uint32 n)
{
    uint32 i;
    uint32 diff = 0u;

    for(i = 0u; i < n; i++)
    {
        diff |= (uint32)(a[i] ^ b[i]);
    }
    return (diff == 0u) ? 1 : 0;
}

/* login / logout / help stay usable while locked: without them the console
 * could never be unlocked, and "help" is what tells the operator why. */
static int auth_exempt(const char *name)
{
    return (auth_streq(name, "login") != 0) ||
           (auth_streq(name, "logout") != 0) ||
           (auth_streq(name, "help") != 0);
}

/* ------------------------------------------------------------ public API */

void arkrtos_shell_auth_init(void)
{
    s_auth_locked      = 1;
    s_auth_locked_hard = 0;
    s_auth_fails       = 0;
}

int arkrtos_shell_auth_locked(void)
{
    return s_auth_locked;
}

int arkrtos_shell_auth_gate(const char *name)
{
    if(name == 0)
    {
        return -1;
    }
    if(auth_exempt(name) != 0)
    {
        return 0;
    }
    if(s_auth_locked == 0)
    {
        return 0;
    }

    if(s_auth_locked_hard != 0)
    {
        ark_shell_printf("login: console locked until reset (%d wrong passwords)\r\n",
                         s_auth_fails);
    }
    else
    {
        ark_shell_printf("login: console is locked, type 'login <password>'\r\n");
    }
    return -1;
}

int arkrtos_shell_auth_cmd_login(int argc, char **argv)
{
    arkrtos_sha256_t ctx;
    uint8            digest[ARKRTOS_SHA256_LEN];
    uint32           i;

    if(argc != 2)
    {
        ark_shell_printf("usage: login <password>\r\n");
        return 1;
    }
    if(s_auth_locked_hard != 0)
    {
        ark_shell_printf("login: locked until reset (%d wrong passwords); reboot to try again\r\n",
                         s_auth_fails);
        return 1;
    }
    if(s_auth_locked == 0)
    {
        ark_shell_printf("login: already logged in\r\n");
        return 0;
    }

    arkrtos_sha256_init(&ctx);
    arkrtos_sha256_update(&ctx, s_auth_salt, 16u);
    arkrtos_sha256_update(&ctx, (const uint8 *)argv[1], auth_strlen(argv[1]));
    arkrtos_sha256_final(&ctx, digest);

    if(auth_digest_equal(digest, s_auth_digest, ARKRTOS_SHA256_LEN) != 0)
    {
        for(i = 0u; i < ARKRTOS_SHA256_LEN; i++) { digest[i] = 0u; }
        s_auth_locked = 0;
        s_auth_fails  = 0;
        ark_shell_printf("login: ok, console unlocked\r\n");
        return 0;
    }

    for(i = 0u; i < ARKRTOS_SHA256_LEN; i++) { digest[i] = 0u; }
    s_auth_fails++;
#if (ARKRTOS_USE_AUDIT_LOG == 1)
    /* The trail gets the attempt number, not the password and not its digest:
     * an audit record is meant to be readable by whoever picks up the board,
     * and "how many times did someone guess" is the whole forensic value. */
    (void)arkrtos_audit_log_record(ARKRTOS_AUDIT_EV_AUTH_FAIL,
                                   (uint32)arkrtos_current_task_id,
                                   (uint32)s_auth_fails);
#endif
    if(s_auth_fails >= ARKRTOS_SHELL_AUTH_TRIES)
    {
        s_auth_locked_hard = 1;
#if (ARKRTOS_USE_AUDIT_LOG == 1)
        (void)arkrtos_audit_log_record(ARKRTOS_AUDIT_EV_AUTH_LOCK,
                                       (uint32)arkrtos_current_task_id,
                                       (uint32)ARKRTOS_SHELL_AUTH_TRIES);
#endif
        ark_shell_printf("login: wrong password, console locked until reset (%d/%d)\r\n",
                         s_auth_fails, ARKRTOS_SHELL_AUTH_TRIES);
    }
    else
    {
        ark_shell_printf("login: wrong password (%d/%d)\r\n",
                         s_auth_fails, ARKRTOS_SHELL_AUTH_TRIES);
    }
    return 1;
}

int arkrtos_shell_auth_cmd_logout(int argc, char **argv)
{
    (void)argc;
    (void)argv;

    if(s_auth_locked_hard != 0)
    {
        ark_shell_printf("logout: console already locked until reset\r\n");
        return 0;
    }
    if(s_auth_locked != 0)
    {
        ark_shell_printf("logout: console is already locked\r\n");
        return 0;
    }

    s_auth_locked = 1;
    s_auth_fails  = 0;
    ark_shell_printf("logout: console locked\r\n");
    return 0;
}

#endif /* ARKRTOS_USE_SHELL_AUTH */
